create table if not exists public.kms_movies(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,type text not null default 'Movie' check(type in ('Movie','Series')),genre text not null default 'Drama',year integer,poster_url text,video_url text,download_url text,description text,description_rw text,translator text default 'KMS',featured boolean not null default false,published boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.kms_episodes(id uuid primary key default gen_random_uuid(),movie_id uuid not null references public.kms_movies(id) on delete cascade,name text not null,episode_number integer not null,video_url text,download_url text,created_at timestamptz not null default now(),unique(movie_id,episode_number));
create table if not exists public.kms_trailers(id uuid primary key default gen_random_uuid(),movie_id uuid not null references public.kms_movies(id) on delete cascade,youtube_video_id text not null,title text,channel_title text,thumbnail_url text,is_primary boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.kms_translations(id uuid primary key default gen_random_uuid(),movie_id uuid references public.kms_movies(id) on delete cascade,source_language text not null default 'en',target_language text not null default 'rw',source_text text not null,translated_text text not null,provider text not null default 'google-cloud-translation',created_at timestamptz not null default now(),unique(movie_id,source_language,target_language,source_text));
alter table public.kms_movies enable row level security;alter table public.kms_episodes enable row level security;alter table public.kms_trailers enable row level security;alter table public.kms_translations enable row level security;
drop policy if exists "kms public read movies" on public.kms_movies;create policy "kms public read movies" on public.kms_movies for select to anon,authenticated using(published=true);
drop policy if exists "kms public read episodes" on public.kms_episodes;create policy "kms public read episodes" on public.kms_episodes for select to anon,authenticated using(exists(select 1 from public.kms_movies m where m.id=movie_id and m.published=true));
drop policy if exists "kms public read trailers" on public.kms_trailers;create policy "kms public read trailers" on public.kms_trailers for select to anon,authenticated using(exists(select 1 from public.kms_movies m where m.id=movie_id and m.published=true));
drop policy if exists "kms public read translations" on public.kms_translations;create policy "kms public read translations" on public.kms_translations for select to anon,authenticated using(movie_id is null or exists(select 1 from public.kms_movies m where m.id=movie_id and m.published=true));